void kernel_seidel_2d(int tsteps, int n, DATA_TYPE *A, int n) {
    // Initialize local loop variables
    int t, i, j;
    #pragma omp parallel
    {
        #pragma omp master
        {
            // Iterate over the number of time steps
            for (t = 0; t < tsteps; t++) {
                // Distribute the work among the available threads
                #pragma omp for schedule(static) collapse(2)
                {
                    // Iterate over the number of rows
                    for (i = 1; i < n - 2; i++) {
                        // Iterate over the number of columns
                        for (j = 1; j < n - 2; j++) {
                            // Calculate the average of its neighboring values
                            A[i][j] = (A[i + 1][j] + A[i - 1][j] + A[i][j + 1] + A[i][j - 1]) / 4.0;
                        }
                    }
                }
            }
        }
    }
}

