static void kernel_covariance(int m, int n, DATA_TYPE float_n, DATA_TYPE POLYBENCH_2D(data,M,N,m,n), DATA_TYPE POLYBENCH_2D(symmat,M,M,m,m), DATA_TYPE POLYBENCH_1D(mean,M,m)) {
    // Initialize the mean array
    for (int j = 0; j < n; j++) {
        mean[j] = 0.0;
    }

    // Initialize the covariance matrix
    for (int j1 = 0; j1 < n; j1++) {
        for (int j2 = 0; j2 < n; j2++) {
            symmat[j1][j2] = 0.0;
        }
    }

    // Parallelize the computation
    #pragma omp parallel for
    for (int j = 0; j < n; j++) {
        // Compute the mean of each column
        for (int i = 0; i < m; i++) {
            mean[j] += data[i][j];
        }

        // Center the data
        for (int i = 0; i < m; i++) {
            data[i][j] -= mean[j];
        }
    }

    // Compute the covariance matrix
    #pragma omp parallel for
    for (int j1 = 0; j1 < n; j1++) {
        for (int j2 = 0; j2 < n; j2++) {
            symmat[j1][j2] += data[i][j1] * data[i][j2];
        }
    }
