    for (int i = 0; i < n; ++i) {
        y[i] = b[i];
    }

    // Back substitution
    #pragma omp parallel for
    for (int i = n - 1; i >= 0; --i) {
        x[i] = (y[i] - A[i][i]) / A[i][i];
    }
